"office-family-books":{"rev":"a7792c922d5e26e16f735ead8497ae678d9a3cdea2045a44f3e7168261113ed1","strings":{"name":"Grandir avec des livres · livres pour les tout-petits","intro":"Une séance Né.e pour lire à l’Espace Jean Perriard.","age":"0–4 ans","schedule":"1er octobre 2026 · 09:15–09:45","price":"Gratuit, sans inscription","address":"Route de Chantemerle 60, 1763 Granges-Paccot","notes[0]":"Le programme est explicitement désigné « parents-enfants ». La langue de la séance n’est pas indiquée. Les places disponibles ne sont pas confirmées.","practical.indoor.text":"Espace Jean Perriard","practical.booking.text":"Sans inscription","practical.duration.text":"30 minutes","practical.commitment.text":"Séance unique gratuite","research.findings[0].field":"Format et âge","research.findings[0].text":"Grandir avec des livres est une séance pour les parents avec des enfants de 0–4 ans.","research.findings[1].field":"Date et lieu","research.findings[1].text":"Jeudi 1er octobre 2026, 09:15–09:45, Espace Jean Perriard, Route de Chantemerle 60, Granges-Paccot.","research.findings[2].field":"Participation","research.findings[2].text":"Le programme d’automne indique : gratuit et sans inscription.","research.remaining[0]":"La langue de la séance, l’accès aux locaux avec une poussette et les conditions pour les familles d’une autre commune.","contacts[0].name":"Office familial · ateliers découvertes","sources[0].label":"Programme d’automne 2026 : âge, lieux, dates et conditions","sources[1].label":"Annonces officielles"}},
"office-family-workshops":{"rev":"7744cae52410064091bb730eaf0112247f233b0a737cd72c4cc8af28e51a32a8","strings":{"name":"Office familial · ateliers en famille","intro":"Atelier d’hiver gratuit « RITUELS ET PETITES HISTOIRES DU SOIR » dans les locaux de l’Office familial, Avenue de la Gare 14, Fribourg, le mardi 1er décembre 2026, 9:30–10:30, sans inscription.","age":"0–5 ans","schedule":"Mardi 1er décembre 2026, 9:30–10:30","price":"Gratuit, sans inscription","address":"Avenue de la Gare 14, 1700 Fribourg","events[0].title":"RITUELS ET PETITES HISTOIRES DU SOIR","events[0].address":"Avenue de la Gare 14, Fribourg","notes[0]":"Le programme est explicitement décrit comme parents-enfants. La langue de chaque séance n’est pas indiquée. La confirmation des places libres n’a pas été reçue.","practical.indoor.text":"Les séances ont lieu à l’intérieur, à l’Office familial","practical.access.text":"3e étage ; vérifier s’il y a un ascenseur et si l’accès avec une poussette est possible","practical.booking.text":"Gratuit, sans inscription préalable","practical.duration.text":"Une heure","practical.commitment.text":"Séances individuelles, pas besoin d’acheter un cours","research.findings[0].field":"Format conjoint","research.findings[0].text":"Le programme d’automne décrit les ateliers comme des séances pour les parents avec des enfants de 0–5 ans.","research.findings[1].field":"Participation","research.findings[1].text":"Le programme indique que l’atelier est gratuit et qu’aucune inscription préalable n’est nécessaire.","research.findings[2].field":"Atelier d’hiver sur la page officielle d’actualités","research.findings[2].text":"La page d’actualités de l’Office familial annonce un atelier d’hiver gratuit, « RITUELS ET PETITES HISTOIRES DU SOIR », le mardi 1er décembre 2026, 9:30–10:30, à l’Avenue de la Gare 14, Fribourg, sans inscription.","research.findings[3].field":"Atelier du 17 novembre","research.findings[3].text":"La page d’actualités de l’Office familial, consultée le 31 octobre 2026, annonce un troisième atelier d’automne gratuit, « Le petit enfant à la découverte de son corps », le mardi 17 novembre, 9:30–10:30, à l’Avenue de la Gare 14, Fribourg, sans inscription. La page n’indique aucune année pour cette date, il n’est donc pas ajouté aux séances datées.","research.findings[4].field":"Atelier d’hiver sur la page officielle d’actualités","research.findings[4].text":"Le 3 novembre 2026, la page d’actualités de l’Office familial annonce toujours l’atelier d’hiver gratuit « RITUELS ET PETITES HISTOIRES DU SOIR » le mardi 1er décembre 2026, 9:30–10:30, dans les locaux de l’organisateur, Avenue de la Gare 14, Fribourg, décrit comme gratuit et sans inscription.","research.findings[5].field":"Atelier d’hiver sur la page officielle d’actualités","research.findings[5].text":"La page d’actualités de l’Office familial, relue le 7 novembre 2026, annonce l’atelier d’hiver gratuit « RITUELS ET PETITES HISTOIRES DU SOIR » le mardi 1er décembre 2026, 9:30–10:30, dans les locaux de l’organisateur, Avenue de la Gare 14, Fribourg, sans inscription.","research.findings[6].field":"Atelier du 15 décembre sur la page officielle d’actualités","research.findings[6].text":"Le 20 novembre 2026, la page d’actualités de l’Office familial annonce un autre atelier d’hiver gratuit, « Jeux pour favoriser la perception de soi », le mardi 15 décembre, 9:30–10:30, dans les locaux de l’organisateur, Avenue de la Gare 14, Fribourg, sans inscription. La page n’indique aucune année pour cette date, il n’est donc pas ajouté aux séances datées.","research.remaining[0]":"La langue de la séance, les conditions pour les familles d’une autre commune, l’ascenseur et la possibilité de partir plus tôt.","research.remaining[1]":"Quelle est la tranche d’âge de chaque atelier, et un parent peut-il ou doit-il rester avec l’enfant ?","research.remaining[2]":"Dans quelle langue les séances se déroulent-elles ?","research.remaining[3]":"Y a-t-il un ascenseur jusqu’au 3e étage, et peut-on entrer avec une poussette ?","research.remaining[4]":"Les familles peuvent-elles quitter une séance plus tôt ?","research.remaining[5]":"L’atelier du 17 novembre « Le petit enfant à la découverte de son corps » a-t-il lieu le 17 novembre 2026 ? La page d’actualités n’indique aucune année.","research.remaining[6]":"L’atelier du 15 décembre « Jeux pour favoriser la perception de soi » a-t-il lieu le 15 décembre 2026 ? La page d’actualités n’indique aucune année.","research.remaining[7]":"Le PDF du programme d’automne 2026 n’a pas pu être lu ; la tranche d’âge, le rôle de l’adulte, la langue et l’accès de chaque atelier restent donc non confirmés.","contacts[0].name":"Office familial · ateliers découvertes","sources[0].label":"Programme d’automne 2026 : âge, lieux, dates et conditions","sources[1].label":"Annonces officielles"}},
